def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.2 * bins
    return np.where(remaining < 0, -np.inf, -np.exp(np.abs(remaining - optimal_remaining)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = 1.0 - (remaining / np.maximum(bins, 1e-8))
    score = np.where(fill_ratio <= 0.9, fill_ratio, 0.9 - (fill_ratio - 0.9) * 5.0)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    unused_ratio = remaining / np.maximum(bins, 1e-8)
    score = np.exp(-unused_ratio) - np.where(unused_ratio < 0.1, 5.0 * (0.1 - unused_ratio), 0.0)
    return np.where(remaining >= 0, score, -np.inf)
